                if (startStr) {
                  const mStart = parseDdMmYyyy(startStr);
                  if (mStart && date < mStart.clone().startOf("day"))
                    return true;
                  if (
                    mStart &&
                    maximumDurationDays !== undefined &&
                    date.isAfter(
                      mStart.clone().add(maximumDurationDays, "days"),
                      "day",
                    )
                  ) {
                    return true;
                  }
                }
                return false;
              }

