              if (isProcessMode && !decision) return;
              try {
                setLoading(true);
                if (isProcessMode && decision) {
                  await onSubmit({
                    decision,
                    notes: trimmedNotes,
                    attachments,
                  });
                } else {
                  await onSubmit({
                    notes: trimmedNotes,
                    attachments,
                  });
                }
              } finally {
                setLoading(false);
              }
            }

